#include <cstddef>
#include <string>
#include <vector>

// "item 0", "item 1", ... "item <count - 1>"
std::vector<std::string> labels(int count)
{
    std::vector<std::string> result{};
    result.reserve(static_cast<std::size_t>(count));
    for (int i{ 0 }; i < count; ++i)
    {
        result.push_back("item " + std::to_string(i));
    }
    return result;
}
